import type { ToolRunner } from "@bithumb-official/bithumb-core";
import type { CliValues } from "../parser.js";
import { toNumber, parseKstDatetime, parseKstTimeOfDay, parseRangedInt, parseEnumInt } from "../parser.js";
import { outputLine, errorLine, printJson, printTable, printKv } from "../formatter.js";

export async function handleMarketCommand(
  run: ToolRunner,
  action: string,
  rest: string[],
  v: CliValues,
  json: boolean,
): Promise<void> {
  switch (action) {
    case "markets":
      return cmdMarkets(run, { isDetails: v.isDetails, json });
    case "ticker":
      return cmdTicker(run, rest[0] ?? v.market, json);
    case "orderbook":
      return cmdOrderbook(run, rest[0] ?? v.market, json);
    case "trades":
      return cmdTrades(run, rest[0] ?? v.market, {
        count: parseRangedInt("count", toNumber(v.count, "count"), 1, 500),
        to: parseKstTimeOfDay(v.to),
        cursor: v.cursor,
        daysAgo: parseRangedInt("days-ago", toNumber(v.daysAgo, "days-ago"), 1, 7),
        json,
      });
    case "candles-minutes":
      return cmdCandlesMinutes(run, rest[0] ?? v.market, {
        unit: parseEnumInt("unit", toNumber(v.unit, "unit"), [1, 3, 5, 10, 15, 30, 60, 240]) ?? 1,
        count: parseRangedInt("count", toNumber(v.count, "count"), 1, 200),
        to: parseKstDatetime(v.to),
        json,
      });
    case "candles-days":
      return cmdCandlesDays(run, rest[0] ?? v.market, {
        count: parseRangedInt("count", toNumber(v.count, "count"), 1, 200),
        to: parseKstDatetime(v.to),
        convertingPriceUnit: v.convertingPriceUnit,
        json,
      });
    case "candles-weeks":
      return cmdCandlesWeeks(run, rest[0] ?? v.market, {
        count: parseRangedInt("count", toNumber(v.count, "count"), 1, 200),
        to: parseKstDatetime(v.to),
        json,
      });
    case "candles-months":
      return cmdCandlesMonths(run, rest[0] ?? v.market, {
        count: parseRangedInt("count", toNumber(v.count, "count"), 1, 200),
        to: parseKstDatetime(v.to),
        json,
      });
    case "warnings":
      return cmdWarnings(run, json);
    case "notices":
      return cmdNotices(run, { count: parseRangedInt("count", toNumber(v.count, "count"), 1, 20), json });
    case "fee-inout":
      return cmdFeeInout(run, rest[0] ?? v.currency, json);
    default:
      errorLine(`Unknown market command: ${action}. Run 'bithumb market --help' for usage.`);
      process.exitCode = 1;
  }
}

async function cmdMarkets(
  run: ToolRunner,
  opts: { isDetails?: boolean; json: boolean },
): Promise<void> {
  const result = await run("market_get_markets", {
    ...(opts.isDetails !== undefined && { isDetails: opts.isDetails }),
  });
  const items = result.data as Record<string, unknown>[];
  if (opts.json) return printJson(items);
  if (!items?.length) { outputLine("No markets found"); return; }
  printTable(items.map((m) => ({
    market: m["market"],
    korean_name: m["korean_name"],
    english_name: m["english_name"],
    ...(opts.isDetails ? { market_warning: m["market_warning"] ?? "" } : {}),
  })));
}

async function cmdTicker(run: ToolRunner, markets: string | undefined, json: boolean): Promise<void> {
  if (!markets) { errorLine("Error: market argument required. Example: bithumb market ticker KRW-BTC"); process.exitCode = 1; return; }
  const result = await run("market_get_ticker", { markets });
  const items = result.data as Record<string, unknown>[];
  if (json) return printJson(items);
  if (!items?.length) { outputLine("No ticker data"); return; }
  printTable(items.map((t) => ({
    market: t["market"],
    trade_price: t["trade_price"],
    signed_change_rate: t["signed_change_rate"],
    acc_trade_volume_24h: t["acc_trade_volume_24h"],
    high_price: t["high_price"],
    low_price: t["low_price"],
  })));
}

async function cmdOrderbook(run: ToolRunner, markets: string | undefined, json: boolean): Promise<void> {
  if (!markets) { errorLine("Error: market argument required. Example: bithumb market orderbook KRW-BTC"); process.exitCode = 1; return; }
  const result = await run("market_get_orderbook", { markets });
  const items = result.data as Record<string, unknown>[];
  if (json) return printJson(items);
  if (!items?.length) { outputLine("No orderbook data"); return; }
  for (const book of items) {
    outputLine(`\n--- ${book["market"]} ---`);
    outputLine(`Total Ask Size: ${book["total_ask_size"]}`);
    outputLine(`Total Bid Size: ${book["total_bid_size"]}`);
    const units = book["orderbook_units"] as Record<string, unknown>[];
    if (units?.length) {
      printTable(units.slice(0, 10).map((u) => ({
        ask_price: u["ask_price"],
        ask_size: u["ask_size"],
        bid_price: u["bid_price"],
        bid_size: u["bid_size"],
      })));
    }
  }
}

async function cmdTrades(
  run: ToolRunner,
  market: string | undefined,
  opts: { count?: number; to?: string; cursor?: string; daysAgo?: number; json: boolean },
): Promise<void> {
  if (!market) { errorLine("Error: market argument required. Example: bithumb market trades KRW-BTC"); process.exitCode = 1; return; }
  const args: Record<string, unknown> = { market };
  if (opts.count !== undefined) args.count = opts.count;
  if (opts.to !== undefined) args.to = opts.to;
  if (opts.cursor !== undefined) args.cursor = opts.cursor;
  if (opts.daysAgo !== undefined) args.daysAgo = opts.daysAgo;
  const result = await run("market_get_trades", args);
  const items = result.data as Record<string, unknown>[];
  if (opts.json) return printJson(items);
  if (!items?.length) { outputLine("No trades found"); return; }
  printTable(items.map((t) => ({
    trade_date_utc: t["trade_date_utc"],
    trade_time_utc: t["trade_time_utc"],
    trade_price: t["trade_price"],
    trade_volume: t["trade_volume"],
    ask_bid: t["ask_bid"],
  })));
}

async function cmdCandlesMinutes(
  run: ToolRunner,
  market: string | undefined,
  opts: { unit: number; count?: number; to?: string; json: boolean },
): Promise<void> {
  if (!market) { errorLine("Error: market argument required"); process.exitCode = 1; return; }
  const args: Record<string, unknown> = { market, unit: opts.unit };
  if (opts.count !== undefined) args.count = opts.count;
  if (opts.to !== undefined) args.to = opts.to;
  const result = await run("market_get_candles_minutes", args);
  const items = result.data as Record<string, unknown>[];
  if (opts.json) return printJson(items);
  if (!items?.length) { outputLine("No candle data"); return; }
  printTable(items.map((c) => ({
    candle_date_time_kst: c["candle_date_time_kst"],
    opening_price: c["opening_price"],
    high_price: c["high_price"],
    low_price: c["low_price"],
    trade_price: c["trade_price"],
    candle_acc_trade_volume: c["candle_acc_trade_volume"],
  })));
}

