async function cmdFeeInout(run: ToolRunner, currency: string | undefined, json: boolean): Promise<void> {
  if (!currency) { errorLine("Error: currency argument required. Example: bithumb market fee-inout BTC"); process.exitCode = 1; return; }
  const result = await run("market_get_fee_inout", { currency });
  const data = result.data;
  if (json) return printJson(data);
  const items = data as Record<string, unknown>[];
  if (Array.isArray(items) && items.length) { printTable(items); return; }
  printJson(data);
}
